import{z as d,x as c,o as r,c as A,q as n,j as E,D as o,d as a,s as i,S as l,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"RISC-V 向量扩展 RVV","description":"","frontmatter":{"title":"RISC-V 向量扩展 RVV","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/rvv-vector.md","filePath":"cs/rvv-vector.md","lastUpdated":1791063341000}'),V={name:"cs/rvv-vector.md"};function v(p,e,B,m,S,h){const s=c("Mermaid");return r(),A("div",null,[e[2]||(e[2]=n('<h1 id="risc-v-向量扩展-rvv" tabindex="-1">RISC-V 向量扩展 RVV <a class="header-anchor" href="#risc-v-向量扩展-rvv" aria-label="Permalink to &quot;RISC-V 向量扩展 RVV&quot;">​</a></h1><div class="epigraph"><p>向量长度寄存器让同一条指令在不同实现上打不同条数：软件按 `vl` 剥循环，硬件用自己的 VLEN 切条，不必为 128/256/512 各写一遍。</p><footer>—— 据 RISC-V Vector Extension Specification；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/simd-extensions">上一课</a>的 AVX 宽度写进 ISA 分代。缺口是 <strong>RVV</strong>：<code>vsetvl</code> 设定本次 <code>vl</code>，寄存器是向量寄存器组，实现选定 VLEN。与 Cray 风格向量更近，与定宽 NEON 对照。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>可移植二进制：同一 <code>vadd.vv</code> 在 VLEN=128 与 512 的核上都能跑，软件用 strip-mining 循环 <code>vl = vsetvl(n)</code>。缺口不是再解释 DLP，而是这套 <strong>配置</strong>：SEW（元素宽）、LMUL（寄存器分组）、掩码寄存器 <code>v0</code>。内存：unit-stride、strided、indexed（gather/scatter）。<span class="marginnote">术语翻译：SEW（选定元素宽度）就是用「一个配置字段告诉硬件『这回把向量寄存器切成多宽的元素』」的手段来做「同一组物理寄存器既能跑 8 位字节也能跑 64 位双字」的事；LMUL 则是把相邻寄存器捆成一组，凑出更长的逻辑向量。</span></p><p>尾与掩码：<code>vta</code>/<code>vma</code> 策略决定未用元素是否保留——向量谓词，后课条件码再对照标量谓词。</p><h3 id="rvv-不是「risc-v-的-avx-512」" tabindex="-1">RVV 不是「RISC-V 的 AVX-512」 <a class="header-anchor" href="#rvv-不是「risc-v-的-avx-512」" aria-label="Permalink to &quot;RVV 不是「RISC-V 的 AVX-512」&quot;">​</a></h3><p>没有强制 512 位。把 RVV 当某代 Intel 宽度的克隆，可移植性故事会破。也不把 RVV 写成训练框架的自动代码生成目标——本栏停在 ISA。</p><p><span class="marginnote">RISC-V Vector Spec 是权威。CA:AQA 向量机章节给直觉。本课不背全部向量指令 opcode。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>循环：测剩余 <code>n</code>，<code>vsetvl</code>，向量 load/运算/store，指针与 <code>n</code> 递减。异常：向量访存的页故障元素位置要精确或按规范重启，实现复杂——点名。与 <a href="/cs/fence-instructions">fence</a>：向量访存参与同一内存模型。<span class="marginnote">数字实例：处理 1000 个 32 位元素。VLEN=128 的核上 vlmax = 128/32 = 4，循环约 250 圈；VLEN=512 上 vlmax = 16，约 63 圈就完——同一段二进制，宽的核自动少绕圈，谁也不用重编译。</span></p>',11)),(r(),E(l,null,{default:o(()=>[i(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%89%A9%E4%BD%99%E5%85%83%E7%B4%A0%20n%22%5D%20--%3E%20VSET%5B%22vsetvl%20%E2%86%92%20vl%22%5D%0A%20%20VSET%20--%3E%20OP%5B%22%E5%90%91%E9%87%8F%E8%BF%90%E7%AE%97%20vl%20%E6%9D%A1%22%5D%0A%20%20OP%20--%3E%20LOOP%5B%22n%20-%3D%20vl%22%5D%0A%20%20LOOP%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8E%8B%E7%BC%A9%E6%98%AF%E6%A0%87%E9%87%8F%E7%A0%81%E5%AF%86%E5%BA%A6%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=t("p",null,"DSP 定点：RVV 有整数与饱和变体，对应饱和课。FMA 有向量版。",-1)),e[4]||(e[4]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=t("p",null,[a("压缩指令减少标量循环开销，与 RVV 叠用。页表走访仍是标量特权机制；向量 load 只是多次翻译或页跨越处理。本课钉「可变 VL」这一 RISC-V 选择。"),t("span",{class:"marginnote"},[a("常见误区：初学者容易以为「RVV 代码要在 512 位核上跑满就必须重新编译」——不必：strip-mining 循环在运行时问 "),t("code",null,"vl"),a(" 要答案，同一个二进制自动吃到更宽的实现；需要重编译的是手写定宽 SIMD 的老习惯。")])],-1)),(r(),E(l,null,{default:o(()=>[i(s,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CFG%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%20vadd.vv%20%E9%85%8D%20SEW%3D32%22%5D%20--%3E%20H1%7B%22%E8%B7%91%E5%9C%A8%20VLEN%3D128%20%E7%9A%84%E6%A0%B8%22%7D%0A%20%20H1%20--%3E%20T1%5B%22%E6%AF%8F%E6%9D%A1%E6%8C%87%E4%BB%A4%E6%89%93%204%20%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%0A%20%20CFG%20--%3E%20H2%7B%22%E8%B7%91%E5%9C%A8%20VLEN%3D512%20%E7%9A%84%E6%A0%B8%22%7D%0A%20%20H2%20--%3E%20T2%5B%22%E6%AF%8F%E6%9D%A1%E6%8C%87%E4%BB%A4%E6%89%93%2016%20%E4%B8%AA%E5%85%83%E7%B4%A0%22%5D%0A%20%20T1%20--%3E%20SAME%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E4%BA%8C%E8%BF%9B%E5%88%B6%20%E4%B8%A4%E8%BE%B9%E9%83%BD%E6%88%90%E7%AB%8B%22%5D%0A%20%20T2%20--%3E%20SAME%0A"})]),fallback:o(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不保证某开源核的 VLEN，不写矩阵扩展（RVV 之外）。不把 autovectorizer bug 当 ISA 定义。</p><p>后课默认：RVV 用 <code>vl</code> 与 VLEN 解耦软件与实现宽度；循环靠 strip-mining。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>vsetvl</code> 设定本次元素数；实现选 VLEN。</li><li>不是定宽 AVX 的改名。</li><li>掩码与尾策略处理短尾与条件。</li><li>出处：RISC-V Vector Extension Spec；Hennessy and Patterson, CA:AQA。</li></ul>',5))])}const D=d(V,[["render",v]]);export{C as __pageData,D as default};
